insert into public.mock_test_questions (test_id, skill, part, q_no, q_type, stem, options, correct_answer, autograde, points, audio_url, image_url, needs_image, tags, explanation_mn, audio_start_sec, audio_end_sec, audio_transcript, tutor_note) values
('M12601','listening',1,1,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m12601/img/q01A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m12601/img/q01B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m12601/img/q01C.webp"}]'::jsonb,'B','auto',1,'/mock-tests/m12601/listening.mp3',null,true,array['sk.listening.match','voc.hsk1','hsk30']::text[],'Сонссон нь «喝茶 (hē chá)» буюу цай уух. B зурагт эр хүн цайны данх ширээн дээр тавьчихаад аяга барьж цай ууж байна.',84.68,103.46,'喝茶','{"why": "Сонссон нь «喝茶 (hē chá)» буюу цай уух. B зурагт эр хүн цайны данх ширээн дээр тавьчихаад аяга барьж цай ууж байна.", "transcript": [{"zh": "喝茶", "pinyin": "hē chá", "mn": "Цай уух"}], "key": "喝茶", "keyMn": "цай уух", "wrong": {"A": "Залуу ширээний ард дэвтэр дээр бичиж, хичээл хийж байна. Цай уух үйлдэл биш.", "C": "Охин аягатай хоол барьж идэж байна. «吃饭» байх байсан, «喝» (уух) биш."}, "trap": "«喝» (уух) ба «吃» (идэх)-ийг андуурч болно.", "tip": "«喝» дараа нь ундаа (茶, 水) ордог, «吃» дараа нь хоол ордог.", "words": [{"zh": "喝", "pinyin": "hē", "mn": "уух"}, {"zh": "茶", "pinyin": "chá", "mn": "цай"}, {"zh": "吃", "pinyin": "chī", "mn": "идэх"}]}'::jsonb),
('M12601','listening',1,2,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m12601/img/q02A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m12601/img/q02B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m12601/img/q02C.webp"}]'::jsonb,'C','auto',1,'/mock-tests/m12601/listening.mp3',null,true,array['sk.listening.match','voc.hsk1','hsk30']::text[],'Сонссон нь «做午饭 (zuò wǔfàn)» буюу өдрийн хоол хийх. C зурагт эр хүн хийн зуухан дээр тогоо барьж хоол хийж байна.',103.76,124.29,'做午饭','{"why": "Сонссон нь «做午饭 (zuò wǔfàn)» буюу өдрийн хоол хийх. C зурагт эр хүн хийн зуухан дээр тогоо барьж хоол хийж байна.", "transcript": [{"zh": "做午饭", "pinyin": "zuò wǔfàn", "mn": "Өдрийн хоол хийх"}], "key": "做午饭", "keyMn": "өдрийн хоол хийх", "wrong": {"A": "Настай эмэгтэй буйдан дээр сэтгүүл барьж, утсаар ярьж байна. Хоол хийхгүй байна.", "B": "Хүн орон дээр суугаад гараа дээш сунган эвшиж байна (сэрж байгаа). Хоол хийх зураг биш."}, "tip": "«做饭» = хоол хийх. «午饭» = өдрийн хоол.", "words": [{"zh": "做", "pinyin": "zuò", "mn": "хийх"}, {"zh": "午饭", "pinyin": "wǔfàn", "mn": "өдрийн хоол"}, {"zh": "饭", "pinyin": "fàn", "mn": "хоол, будаа"}]}'::jsonb),
('M12601','listening',1,3,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m12601/img/q03A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m12601/img/q03B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m12601/img/q03C.webp"}]'::jsonb,'B','auto',1,'/mock-tests/m12601/listening.mp3',null,true,array['sk.listening.match','voc.hsk1','hsk30']::text[],'Сонссон нь «两个面包 (liǎng ge miànbāo)» буюу хоёр талх. B зурагт хоёр ширхэг талх байна.',124.59,146.26,'两个面包','{"why": "Сонссон нь «两个面包 (liǎng ge miànbāo)» буюу хоёр талх. B зурагт хоёр ширхэг талх байна.", "transcript": [{"zh": "两个面包", "pinyin": "liǎng ge miànbāo", "mn": "Хоёр талх"}], "key": "两个面包", "keyMn": "хоёр талх", "wrong": {"A": "Хоёр сандал байна. Тоо нь «两» таарч байгаа ч эд зүйл нь талх биш.", "C": "Хоёр өндөг байна. Тоо таарч байгаа ч «面包» (талх) биш."}, "trap": "Гурван зурагт бүгд «хоёр» ширхэг байна, тиймээс тоо биш юуг нэрлэснийг сонсох ёстой.", "tip": "Тоо + 个 + эд зүйлийн нэр гэсэн бүтцийн хойд талын нэрийг сайн сонс.", "words": [{"zh": "两", "pinyin": "liǎng", "mn": "хоёр (тоолохдоо)"}, {"zh": "个", "pinyin": "ge", "mn": "ширхэг"}, {"zh": "面包", "pinyin": "miànbāo", "mn": "талх"}]}'::jsonb),
('M12601','listening',1,4,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m12601/img/q04A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m12601/img/q04B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m12601/img/q04C.webp"}]'::jsonb,'A','auto',1,'/mock-tests/m12601/listening.mp3',null,true,array['sk.listening.match','voc.hsk1','hsk30']::text[],'Сонссон нь «在房间学习 (zài fángjiān xuéxí)» буюу өрөөндөө хичээллэх. A зурагт залуу ширээний чийдэнгийн дэргэд дэвтэртээ бичиж хичээллэж байна.',146.56,169.28,'在房间学习','{"why": "Сонссон нь «在房间学习 (zài fángjiān xuéxí)» буюу өрөөндөө хичээллэх. A зурагт залуу ширээний чийдэнгийн дэргэд дэвтэртээ бичиж хичээллэж байна.", "transcript": [{"zh": "在房间学习", "pinyin": "zài fángjiān xuéxí", "mn": "Өрөөндөө хичээллэх"}], "key": "在房间学习", "keyMn": "өрөөндөө хичээллэх", "wrong": {"B": "Хэсэг залуучууд хамт суугаад кино үзэж, инээлдэж байна. Хичээллэж байгаа зураг биш.", "C": "Охин цонхны дэргэд утсаа харж байна. Хичээллэж байгаа зураг биш."}, "tip": "«在 + газар + үйл үг» = тэр газарт ямар нэг зүйл хийх.", "words": [{"zh": "在", "pinyin": "zài", "mn": "-д (байр)"}, {"zh": "房间", "pinyin": "fángjiān", "mn": "өрөө"}, {"zh": "学习", "pinyin": "xuéxí", "mn": "хичээллэх, сурах"}]}'::jsonb),
('M12601','listening',1,5,'match','Сонсоод тохирох зургийг сонго:','[{"key": "A", "text": "", "image_url": "/mock-tests/m12601/img/q05A.webp"}, {"key": "B", "text": "", "image_url": "/mock-tests/m12601/img/q05B.webp"}, {"key": "C", "text": "", "image_url": "/mock-tests/m12601/img/q05C.webp"}]'::jsonb,'C','auto',1,'/mock-tests/m12601/listening.mp3',null,true,array['sk.listening.match','voc.hsk1','hsk30']::text[],'Сонссон нь «漂亮的衣服 (piàoliang de yīfu)» буюу сайхан хувцас. C зурагт гоёмсог цэцэгэн ханцуйтай даашинз байна.',169.58,177.55,'漂亮的衣服','{"why": "Сонссон нь «漂亮的衣服 (piàoliang de yīfu)» буюу сайхан хувцас. C зурагт гоёмсог цэцэгэн ханцуйтай даашинз байна.", "transcript": [{"zh": "漂亮的衣服", "pinyin": "piàoliang de yīfu", "mn": "Сайхан хувцас"}], "key": "漂亮的衣服", "keyMn": "сайхан хувцас", "wrong": {"A": "Ширээн дээр хэд хэдэн хоол байна. Хувцас биш.", "B": "Жимс жимсгэнэ (гүзээлзгэнэ, усан үзэм гэх мэт) байна. Хувцас биш."}, "tip": "«衣服» гэж сонсвол хувцастай зургийг хай.", "words": [{"zh": "漂亮", "pinyin": "piàoliang", "mn": "сайхан, хөөрхөн"}, {"zh": "的", "pinyin": "de", "mn": "-тай (тодотгол)"}, {"zh": "衣服", "pinyin": "yīfu", "mn": "хувцас"}]}'::jsonb),
('M12601','listening',2,6,'choice','','[{"key": "A", "text": "三月"}, {"key": "B", "text": "五个"}, {"key": "C", "text": "星期天"}]'::jsonb,'C','auto',1,'/mock-tests/m12601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk1','hsk30']::text[],'Асуулт «今天星期几? (jīntiān xīngqī jǐ?)» буюу «Өнөөдөр хэдэн гараг вэ?». Гарагийн нэрээр хариулна, тиймээс «星期天 (xīngqītiān)» буюу ням гараг зөв.',225.46,254.81,'今天星期几?','{"why": "Асуулт «今天星期几? (jīntiān xīngqī jǐ?)» буюу «Өнөөдөр хэдэн гараг вэ?». Гарагийн нэрээр хариулна, тиймээс «星期天 (xīngqītiān)» буюу ням гараг зөв.", "transcript": [{"zh": "今天星期几?", "pinyin": "jīntiān xīngqī jǐ?", "mn": "Өнөөдөр хэдэн гараг вэ?"}], "key": "星期几", "keyMn": "Хэдэн гараг", "wrong": {"A": "«三月» (гуравдугаар сар) нь сар. Асуулт нь гарагийн тухай.", "B": "«五个» (тав) нь тоо ширхэг. Гарагийн нэр биш."}, "trap": "Тоо, сар, гарагийн асуултыг андуурна.", "tip": "«几» хэдэн гэсэн асуултын үг, «星期几» = ямар гараг.", "words": [{"zh": "今天", "pinyin": "jīntiān", "mn": "өнөөдөр"}, {"zh": "星期", "pinyin": "xīngqī", "mn": "долоо хоног, гараг"}, {"zh": "几", "pinyin": "jǐ", "mn": "хэдэн"}]}'::jsonb),
('M12601','listening',2,7,'choice','','[{"key": "A", "text": "上课"}, {"key": "B", "text": "书店"}, {"key": "C", "text": "大学生"}]'::jsonb,'B','auto',1,'/mock-tests/m12601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk1','hsk30']::text[],'Асуулт «你现在在哪儿? (nǐ xiànzài zài nǎr?)» буюу «Чи одоо хаана байна?». Газрын нэрээр хариулах ёстой тул «书店 (shūdiàn)» буюу номын дэлгүүр зөв.',255.11,270.97,'你现在在哪儿?','{"why": "Асуулт «你现在在哪儿? (nǐ xiànzài zài nǎr?)» буюу «Чи одоо хаана байна?». Газрын нэрээр хариулах ёстой тул «书店 (shūdiàn)» буюу номын дэлгүүр зөв.", "transcript": [{"zh": "你现在在哪儿?", "pinyin": "nǐ xiànzài zài nǎr?", "mn": "Чи одоо хаана байна?"}], "key": "在哪儿", "keyMn": "хаана байна", "wrong": {"A": "«上课» (хичээл орох) нь үйлдэл. «Хаана» гэсэн асуултад газар хэлэх ёстой.", "C": "«大学生» (их сургуулийн оюутан) нь хүн. Газар биш."}, "tip": "«哪儿» гэж сонсвол газрын нэр хайна.", "words": [{"zh": "现在", "pinyin": "xiànzài", "mn": "одоо"}, {"zh": "哪儿", "pinyin": "nǎr", "mn": "хаана"}, {"zh": "书店", "pinyin": "shūdiàn", "mn": "номын дэлгүүр"}]}'::jsonb),
('M12601','listening',2,8,'choice','','[{"key": "A", "text": "没有"}, {"key": "B", "text": "不知道"}, {"key": "C", "text": "六点十分"}]'::jsonb,'A','auto',1,'/mock-tests/m12601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk1','hsk30']::text[],'Асуулт «请问你有时间吗? (qǐngwèn nǐ yǒu shíjiān ma?)» буюу «Чамд цаг байна уу?». «吗» бүхий асуултад «有 / 没有» гэж хариулна, тиймээс «没有» (байхгүй) зөв.',271.27,301.42,'请问你有时间吗?','{"why": "Асуулт «请问你有时间吗? (qǐngwèn nǐ yǒu shíjiān ma?)» буюу «Чамд цаг байна уу?». «吗» бүхий асуултад «有 / 没有» гэж хариулна, тиймээс «没有» (байхгүй) зөв.", "transcript": [{"zh": "请问你有时间吗?", "pinyin": "qǐngwèn nǐ yǒu shíjiān ma?", "mn": "Уучлаарай, чамд цаг байна уу?"}], "key": "你有时间吗", "keyMn": "Чамд цаг байна уу", "wrong": {"B": "«不知道» (мэдэхгүй) нь «байна уу» гэсэн асуултад дөхөхгүй хариулт.", "C": "«六点十分» (6:10) нь цагийн хариулт. Энд «хэдэн цаг» гэж асуугаагүй."}, "trap": "«时间» (цаг зав)-ыг «цагийн хэмжээ» гэж андуурч «六点十分» сонгож болно.", "tip": "«有……吗?» асуултад «有» эсвэл «没有» гэж хариулна.", "words": [{"zh": "请问", "pinyin": "qǐngwèn", "mn": "уучлаарай, асууя"}, {"zh": "时间", "pinyin": "shíjiān", "mn": "цаг зав"}, {"zh": "没有", "pinyin": "méiyǒu", "mn": "байхгүй"}]}'::jsonb),
('M12601','listening',2,9,'choice','','[{"key": "A", "text": "没关系"}, {"key": "B", "text": "非常好"}, {"key": "C", "text": "很好看"}]'::jsonb,'B','auto',1,'/mock-tests/m12601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk1','hsk30']::text[],'Асуулт «她的中文怎么样? (tā de Zhōngwén zěnmeyàng?)» буюу «Түүний хятад хэл ямар вэ?». «怎么样» нь үнэлгээ асууж байгаа тул «非常好 (fēicháng hǎo)» буюу «маш сайн» зөв.',301.72,325.13,'她的中文怎么样?','{"why": "Асуулт «她的中文怎么样? (tā de Zhōngwén zěnmeyàng?)» буюу «Түүний хятад хэл ямар вэ?». «怎么样» нь үнэлгээ асууж байгаа тул «非常好 (fēicháng hǎo)» буюу «маш сайн» зөв.", "transcript": [{"zh": "她的中文怎么样?", "pinyin": "tā de Zhōngwén zěnmeyàng?", "mn": "Түүний хятад хэл ямар вэ?"}], "key": "怎么样", "keyMn": "ямар вэ", "wrong": {"A": "«没关系» (зүгээр, ямар ч асуудалгүй) нь уучлалын хариу. Үнэлгээ биш.", "C": "«很好看» (маш сайхан харагдах) нь харагдах байдлыг хэлнэ, хэлний чадварт тохирохгүй."}, "trap": "«好» ба «好看» ойролцоо мэт санагдана.", "tip": "«怎么样?» → «很好 / 不错 / 不太好» гэх мэт үнэлгээгээр хариулна.", "words": [{"zh": "中文", "pinyin": "Zhōngwén", "mn": "хятад хэл"}, {"zh": "怎么样", "pinyin": "zěnmeyàng", "mn": "ямар вэ"}, {"zh": "非常", "pinyin": "fēicháng", "mn": "маш"}]}'::jsonb),
('M12601','listening',2,10,'choice','','[{"key": "A", "text": "十个"}, {"key": "B", "text": "不好吃"}, {"key": "C", "text": "在饭店"}]'::jsonb,'A','auto',1,'/mock-tests/m12601/listening.mp3',null,false,array['sk.listening.choice','voc.hsk1','hsk30']::text[],'Асуулт «你吃几个饺子? (nǐ chī jǐ ge jiǎozi?)» буюу «Чи хэдэн банш (жяоз) иднэ вэ?». «几个» нь тоо асууна, тиймээс «十个 (shí ge)» буюу арван ширхэг зөв.',325.43,381.23,'你吃几个饺子?','{"why": "Асуулт «你吃几个饺子? (nǐ chī jǐ ge jiǎozi?)» буюу «Чи хэдэн банш (жяоз) иднэ вэ?». «几个» нь тоо асууна, тиймээс «十个 (shí ge)» буюу арван ширхэг зөв.", "transcript": [{"zh": "你吃几个饺子?", "pinyin": "nǐ chī jǐ ge jiǎozi?", "mn": "Чи хэдэн жяоз идэх вэ?"}], "key": "几个", "keyMn": "хэдэн ширхэг", "wrong": {"B": "«不好吃» (амттай биш) нь амтын тухай. Тоо асуусан.", "C": "«在饭店» (ресторант) нь газар. Тоо биш."}, "tip": "«几个» гэж сонсвол тоо хайна.", "words": [{"zh": "几", "pinyin": "jǐ", "mn": "хэдэн"}, {"zh": "个", "pinyin": "ge", "mn": "ширхэг"}, {"zh": "饺子", "pinyin": "jiǎozi", "mn": "жяоз, чанасан банш"}]}'::jsonb),
